import{_ as t,o as s,c as a,a2 as o}from"./chunks/framework.hw3Av5Vn.js";const n="/llamatron/assets/clip.wJ3TbSl4.svg",i="/llamatron/assets/clip_strum.Cb1DggVG.svg",r="/llamatron/assets/chain_list.DCXMIrFd.svg",u=JSON.parse('{"title":"Clips","description":"","frontmatter":{},"headers":[],"relativePath":"CLIPS.md","filePath":"CLIPS.md"}'),h={name:"CLIPS.md"};function c(d,e,l,p,g,m){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="clips" tabindex="-1">Clips <a class="header-anchor" href="#clips" aria-label="Permalink to &quot;Clips&quot;">​</a></h1><p>A clip is what a track plays in a scene: a pattern, and the settings that change how the pattern plays there. This page covers the clip page.</p><p><img src="'+n+'" alt="The Clip page"></p><h2 id="clips-on-arrange" tabindex="-1">Clips on Arrange <a class="header-anchor" href="#clips-on-arrange" aria-label="Permalink to &quot;Clips on Arrange&quot;">​</a></h2><p>A clip sits where a scene&#39;s row and a track&#39;s column meet on Arrange, so the clip page&#39;s crumb pairs the two, such as <code>ARRANGE › clip: (verse, bass)</code>. The crumbs always say where <code>Esc</code> goes back to. The pattern editor opened with <code>P</code> from a clip reads <code>ARRANGE › pattern: bass line</code> when opened from Arrange, <code>ARRANGE › clip: (verse, bass) › pattern: bass line</code> when opened from the clip page, and <code>PATTERNS › bass line</code> only when the Patterns page opened it.</p><h2 id="clip-settings" tabindex="-1">Clip Settings <a class="header-anchor" href="#clip-settings" aria-label="Permalink to &quot;Clip Settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td>Name</td><td>A name of the clip&#39;s own, shown on the grid and used for the clip in Live and in the clip tree&#39;s file names. Without one, the clip goes by its pattern&#39;s name. <code>Bksp</code> clears it.</td></tr><tr><td>Pattern</td><td>The pattern the clip plays. <code>P</code> opens the pattern in the pattern editor from any row of the page, and <code>Esc</code> comes back.</td></tr><tr><td>Scale</td><td>A scale of the clip&#39;s own, which wins over the scene&#39;s and the song&#39;s, so that one track can play in another key or mode. <code>Enter</code> picks one, and <code>Bksp</code> goes back to the scene&#39;s, shown with where it comes from, such as <code>A Minor (from scene)</code>.</td></tr><tr><td>Chains</td><td>The chains of generators the clip runs, in order. <code>Enter</code> opens the list, where <code>A</code> adds a chain, <code>M</code> moves one and <code>Bksp</code> takes one out; <code>Bksp</code> on the field clears them all. A clip runs its own chains first, then its scene&#39;s, then its track&#39;s. See <a href="./CHAINS">Chains</a>.</td></tr><tr><td>Repeat</td><td>How many times the clip plays, from 1 to 9999, before staying silent while the scene&#39;s other clips finish.</td></tr><tr><td>Loop</td><td>Plays the clip until the scene&#39;s longest clip that doesn&#39;t loop is done. <code>Space</code> or <code>Enter</code> toggles it.</td></tr><tr><td>Direction</td><td>Overrides the play direction of the clip&#39;s pattern, and of the pattern it morphs to. <code>Bksp</code> goes back to the patterns&#39; own, shown as <code>forward (from pattern)</code> or the like.</td></tr><tr><td>Morph to</td><td>With Repeat above 1, a second pattern to change into across the repeats.</td></tr><tr><td>Morph direction</td><td><code>left</code>, <code>right</code> or <code>middle</code>: where the change sweeps in from.</td></tr><tr><td>Grab track</td><td>Another track in the scene, whose notes the pattern&#39;s Grab steps play. <code>Bksp</code> sets none.</td></tr><tr><td>Advance</td><td>What the clip does in real-time playback when it finishes, as described under Advance below. <code>Enter</code> chooses. A clip that sets none shows the set&#39;s default, such as <code>With Scene (from set)</code>.</td></tr><tr><td>+ Strum</td><td>A section, closed until opened, like the track editor&#39;s: Strum direction <code>(track)</code> takes the track&#39;s strum, shown as the direction it takes, such as <code>down (from track)</code>, <code>off</code> strums nothing whatever the track says, and any other direction strums this clip its own way. See <a href="./generators/STRUM">Strum</a>.</td></tr><tr><td>+ Density, + Swell, + Articulate</td><td>Sections, closed until opened, like the Scene page&#39;s, shaping this clip across its own length. A shape set here wins over the scene&#39;s, and a generator in the clip&#39;s chains wins over both.</td></tr><tr><td>Play, Stop</td><td>Buttons under the settings, which do what <code>L</code> (Listen) does: play the clip in real time as its scene would, with its chains, grabs, scale and direction, again and again until <code>L</code> is pressed again or Stop is. When the clip&#39;s track has no instrument, a list asks which of the set&#39;s instruments to listen through, for this listening alone. While the Real Time switch is off, the clip plays through General MIDI in <a href="./FLUIDSYNTH">FluidSynth</a> instead, the piano, or the drum kit for drums. See <a href="./PLAYING_LIVE">Playing Live</a>.</td></tr></tbody></table><h2 id="morphing" tabindex="-1">Morphing <a class="header-anchor" href="#morphing" aria-label="Permalink to &quot;Morphing&quot;">​</a></h2><p>Morph to and Morph direction appear only when Repeat is above 1, and setting Repeat back to 1 removes the morph. The pattern being morphed to is looped or cut to the clip&#39;s length, and follows the clip&#39;s Direction when the clip has one; otherwise it follows its own pattern&#39;s direction, so a clip set to <code>eitherway</code> can finish its morph playing the second pattern backwards. A pattern with no notes morphs too, carrying its CC values and register changes across. The pattern being morphed to never grabs, and uses the registers without adding to them.</p><h2 id="grabbing-notes" tabindex="-1">Grabbing Notes <a class="header-anchor" href="#grabbing-notes" aria-label="Permalink to &quot;Grabbing Notes&quot;">​</a></h2><p>Grab track works like the Cirklon&#39;s note grab, and changes only the steps that the pattern&#39;s Grab row marks. Each marked step plays the note that the other track most recently started, at or before that step: the note the other track is playing, or the last note it played if it is silent. If the other track hasn&#39;t played anything yet, the step keeps its own note, or stays silent if the step has none.</p><p>When the other track plays a chord, the step takes the chord&#39;s root, the note the chord was built on, whatever its inversion or voice leading. A grab step with nothing on its Chord row plays that one note, and a grab step with a chord on its Chord row plays the chord with the grabbed note at the bottom: when the bass plays D and the step&#39;s chord is <code>m7</code>, the step plays D, F, A and C. The scale chords, <code>3</code> to <code>13</code>, add notes of the clip&#39;s scale above the grabbed note. A grab hears the other track after that track&#39;s chains run, so grabbing from an arpeggiated track takes the arpeggio&#39;s notes. Every other step, and everything else about the clip, such as its rhythm and velocity, stays the clip&#39;s own, and the grabbing track&#39;s transpose still applies.</p><p>Because grabbing is set on the clip, one pattern can grab from different tracks in different clips. A clip can grab from a track that grabs from another, but never in a circle: the clip page refuses a grab that would close a circle and says which clips to change, pasting a clip drops such a grab, and a set file with a circle stops exporting with a message naming the tracks.</p><h2 id="advance" tabindex="-1">Advance <a class="header-anchor" href="#advance" aria-label="Permalink to &quot;Advance&quot;">​</a></h2><p>Advance is Live&#39;s follow action: what a clip does in real-time playback when it finishes. No export reads it.</p><ul><li>&quot;With Scene&quot; starts the clip directly below when the whole scene is done.</li><li>&quot;Next&quot; starts the clip directly below as soon as this clip&#39;s own repeats end, whatever the rest of the scene is doing.</li><li>&quot;Off&quot; starts nothing, so the track falls silent until something launches it.</li></ul><p>A scene is done when every clip in it that doesn&#39;t loop has finished its repeats. A looping clip loops on until the scene below starts, so a scene whose every clip loops plays until you start something else. When the scene below has Launch together on, a start reaching any of its clips launches the whole scene and stops everything still playing in the scene above. A clip that sets nothing shows the Set File page&#39;s Default follow action as its own.</p><h2 id="clip-strum-and-chains" tabindex="-1">Clip Strum and Chains <a class="header-anchor" href="#clip-strum-and-chains" aria-label="Permalink to &quot;Clip Strum and Chains&quot;">​</a></h2><p>A clip&#39;s sections set its own strum and shapes, over those of its track and its scene. In <code>examples/learning/13_classic_strum.yml</code>, this clip strums by the beat with a tight spread:</p><p><img src="'+i+'" alt="A clip&#39;s Strum section open"></p><p><code>Enter</code> on a clip&#39;s Chains field opens the list of chains the clip runs, where <code>A</code> adds one:</p><p><img src="'+r+'" alt="A clip&#39;s chains"></p>',22)])])}const b=t(h,[["render",c]]);export{u as __pageData,b as default};
